    }

    public function prepareVisibleDataInList(SnippetVersion $content): SnippetVersionAttributes
    {
        return $this->prepareVisibleDataCallback($content, true);
    }
    public function prepareVisibleData(SnippetVersion $content): SnippetVersionAttributes
    {
        return $this->prepareVisibleDataCallback($content, false);
    }
    public function copyWithFixed(SnippetVersionAttributes $attributes, ?SnippetVersion $original = null): SnippetVersionAttributes
    {
        $this->logDebug("Copy with fixed for Snippet version");
        $span = $this->startSpan("Copy with fixed for  Snippet version");
        try {
            $visible = $this->visiblesReferences($attributes);
            $fixed = $this->fieldsToFix($original);
            foreach ($fixed as $field) {
                $visible->unset($field);
            }
            $result = $this->dispatcher->dispatch(new SnippetVersionPresetValues($attributes, $original));
            return $result->attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function copyWithHidden(SnippetVersionAttributes $attributes, ?SnippetVersion $original = null): SnippetVersionAttributes
    {
        $this->logDebug("Copy with hidden for Snippet version");
        $span = $this->startSpan("Copy with hidden for  Snippet version");
        try {
            $hidden = $this->fieldsToHide($original);
            foreach ($hidden as $field) {
                $attributes->unset($field);
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function checkVisibility(Iterator|string|SnippetVersionRef $value): bool
    {
        $this->logDebug("Check visibility of an iterator for Snippet version");
        $span = $this->startSpan("Check visibility of an iterator for  Snippet version");
        try {
            if (is_string($value)) {
                return !!$this->retrieveVisibleForUpdate(new SnippetVersionRef($value));
            } elseif ($value instanceof SnippetVersionRef) {
                return !!$this->retrieveVisibleForUpdate($value);
            } elseif ($value instanceof Iterator) {
                $ids = [];
                foreach ($value as $val) {
                    $ids[] = $val->uid();
                }
                $filter = new SnippetVersionFilter(uids: $ids);
                return count($ids) == $this->countVisibles($filter);
            } else {
                return false;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisibles(SnippetVersionFilter $filter, ?SnippetVersionCursor $cursor = null): SnippetVersionSlide
    {
        $this->logDebug("List visibles for Snippet version");
        $span = $this->startSpan("List visibles for  Snippet version");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->readGateway->list($visibleFilter, $cursor);
            return $result->slide(function (SnippetVersion $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
