            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisible(SnippetVersionRef $ref): ?SnippetVersion
    {
        $this->logDebug("Retrieve visible for Snippet version");
        $span = $this->startSpan("Retrieve visible for  Snippet version");
        try {
            $filter = new SnippetVersionFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->readGateway->retrieve($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
