    {
        $this->logDebug("Retrieve visible for update for Snippet version");
        $span = $this->startSpan("Retrieve visible for update for  Snippet version");
        try {
            $filter = new SnippetVersionFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->writeGateway->retrieveForUpdate($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
