    public function fieldsToFix(?SnippetVersionRef $ref = null): array
    {
        $this->logDebug("Check fields to fix for Snippet version");
        $span = $this->startSpan("Check fields for fix for Snippet version");
        try {
            $result = $this->dispatcher->dispatch(new SnippetVersionCollectNonEditableFields(SnippetVersion::calculatedFields(), $ref));
            return array_values(array_unique(array_merge($this->fieldsToHide($ref), $result->fields)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
