    private function visiblesReferences(SnippetVersionAttributes $attributes): SnippetVersionAttributes
    {
        $this->logDebug("Check visibility of parent references for Snippet version");
        $span = $this->startSpan("Check visibility of parent references for  Snippet version");
        try {
            $snippet = $attributes->getSnippet();
            if (null !== $snippet && !$this->snippetVisibilityService->checkVisibility($snippet)) {
                throw new NotFoundException("Unknown Snippet " . ($snippet->uid() ?? 'no-id'));
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
