            $result = $this->dispatcher->dispatch(new SnippetVersionRestrictFilterToVisibility($filter));
            return $result->snippetVersionFilter;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function evaluatePostVisibility(SnippetVersion $value): bool
    {
        $this->logDebug("Check if item is visible for Snippet version");
        $span = $this->startSpan("Check if item is visible for  Snippet version");
        try {
            $result = $this->dispatcher->dispatch(new SnippetVersionVisibilityCheck(true, $value));
